guidance.correct_example:
def fetch_user(a_id: int) -> Result[User]:
    b_continue = True
    result: Result[User] = INVALID_RESULT
    try:
        user = db.query(a_id)
    except ConnectionError as e:
        result = Result.failure(f'DB connection failed: {e}')
        b_continue = False
    if b_continue:
        result = Result.success(user)
    return result

guidance.incorrect_example:
def fetch_user(a_id: int) -> Result[User]:
    user = db.query(a_id)
    if user is None:
        raise ValueError('User not found')
    return Result.success(user)
